import json

class IntegrityError(Exception):
    pass

class AuditWAL:
    def __init__(self, path):
        self.path = path
        self._count = 0

    def append(self, event):
        # BUG: simple non-atomic JSON lines, no magic, no CRC32, no fsync
        with open(self.path, 'a') as f:
            f.write(json.dumps(event) + '\n')
        seq = self._count
        self._count += 1
        return seq

    def recover(self):
        # BUG: fails to handle framing, CRC32 or torn writes
        records = []
        try:
            with open(self.path, 'r') as f:
                for line in f:
                    records.append(json.loads(line))
        except FileNotFoundError:
            pass
        return records
